      "keySentence": "recent comprehensive empirical audits demonstrate that humanity has already breached at least six of these nine critical thresholds, plunging several foundational Earth subsystems into dangerously destabilised states.",
      "collocation": "Passage 'breached at least six of these nine critical thresholds, plunging several foundational Earth subsystems into dangerously destabilised states' ➔ Option 'Humanity has already crossed multiple interdependent ecological limits, risking irreversible systemic collapse'",
      "explanation": "본문에서 지구위험한계선(Planetary Boundaries) 프레임워크의 핵심 경고로 '인류가 이미 9개 한계 중 최소 6개를 초과하여 상호 연결된 지구 시스템이 비선형적인 파국적 위험에 처했다'고 분명히 밝혔습니다. 따라서 ①번이 정확합니다. ②번은 한계선이 모두 회복되었다는 정반대 오답이며, ③번은 상호 무관하다는 왜곡, ④번은 물리적 지구가 팽창한다는 터무니없는 오답입니다.",
      "translation": "[본문 해석]\n약 11,700년 동안 이어진 홀로세(Holocene)는 농경과 도시 문명이 번영할 수 있었던 안정적인 기후 환경을 제공했습니다. 그러나 인간의 산업 문명이 지구 생물물리학적 균형을 근본적으로 변화시키면서 인류는 '인류세(Anthropocene)'라는 새로운 지질학적 시대로 진입했습니다. 지구과학자들은 인류가 안전하게 생존하고 번영할 수 있는 9가지 상호의존적 생물물리학적 한계를 규명한 '지구위험한계선(Planetary Boundaries)' 이론을 정립했습니다. 이 9대 한계에는 온실가스 농도, 오존층 파괴, 해양 산성화, 담수 이용, 질소·인 순환, 신규 화학물질, 토지 이용 변화, 에어로졸 부하, 생물다양성이 포함됩니다. 놀랍게도 최근 연구에 따르면 인류는 이미 이 중 최소 6개의 한계선을 초과하여 지구 하위 시스템을 심각하게 불안정화시켰습니다. 합성 비료 과다 사용으로 인한 질소·인 유출은 수중 부영양화와 무산소 데드존을 양산했고, 생물 멸종 속도는 자연 기준의 수백 배에 달합니다. 특히 이 한계선들은 비선형적으로 얽혀 있어 아마존 열대우림 파괴가 기후변화를 가속하고, 이는 영구동토층 해빙을 유발해 메탄을 대량 방출하는 연쇄 티핑 포인트로 이어집니다. 인류세를 헤쳐 나가기 위해서는 무한 성장에서 탈피하여 지구의 수용 한계 내에서 인류의 번영을 도모하는 재생적 경제 모델로의 전환이 시급합니다.\n\n[보기 해석]\n① 인류가 이미 다수의 상호의존적 생태 한계를 초과하여 돌이킬 수 없는 시스템 붕괴 위험에 직면해 있다 (정답)\n② 지구의 9대 한계선이 이미 산업화 이전의 원시 상태로 완전히 회복되었다\n③ 지구 환경 문제는 서로 아무런 영향을 미치지 않는 독립적인 고립 현상으로 작용한다\n④ 지구는 무한한 경제 확장을 수용하기 위해 물리적 직경을 스스로 팽창시킬 것이다"
