        "translation": "[본문 해석]\n소매업계에서 일회용 플라스틱 용기의 무분별한 확산은 전 세계 해양 생태계를 오염시키며 전례 없는 생태학적 위기를 초래했습니다. 이 딜레마에 맞서 선도적인 슈퍼마켓 체인들은 순환형 리필 모델을 시험 도입하고 있습니다. 고객들은 튼튼하고 규격화된 다회용 용기를 매장에 가져와 자동 벌크 디스펜서에서 건조 식품, 세제, 주방 필수품을 직접 담아 구매합니다. 참여 소비자들은 긍정적 유인책으로 결제 시 소액의 가격 할인 혜택을 받습니다. 이러한 폐쇄 루프 순환 포장 체계는 플라스틱 제조와 폐기물을 현저히 억제하여 책임 있는 소비를 촉진하고 지방자치단체의 쓰레기 매립 부담을 크게 덜어줍니다.\n\n[보기 해석]\n① 쇼핑 결제 시 소액의 금전적 할인 혜택을 제공한다 (정답)\n② 판지에 포장된 물품을 구매하는 사람에게 법적 벌금을 부과한다\n③ 식료품 쇼핑 자격을 등록된 환경 클럽 회원에게만 독점 제한한다\n④ 오프라인 매장에서 구매하는 모든 식료품 가격을 2배로 인상한다"
